  an.name = "Jitter";
  var pp = an.property("ADBE Text Animator Properties").addProperty("ADBE Text Position 3D");
  pp.expression = "posterizeTime(12); seedRandom(textIndex+123+Math.floor(time*12),true); [random(-" + amt + "," + amt + "), random(-" + amt + "," + amt + "), 0]";
